     * @param int $idnivel                 Identificador del nivel de configuraci�n.
     * @return array    Listado de configuraci�n de las variables globales.
     */
    public static function obtenerConfigVarGlobales($idnivel) {

        //Devolviendo el listado de configuraci�n de las variables globales en forma de arreglo.
        return Doctrine_Query::create()
                ->select('vg.idvariableglobal ,vg.abreviatura, 
                    vg.denominacion, cvg.idvariableglobalvalor as idvariableglobalvalor,
                    cvg.valor as valor')
                ->from('NomVariableGlobal vg')
                ->leftjoin('vg.ConfigVariableGlobalValor cvg')
                ->where('vg.idnivelconfiguracion = ?', $idnivel)
                ->fetchArray();
    }

