    /**
     * Obtener la configuraci�n y valores de las variables globales para usar en la nomina
     * 
     * @Autor Ing. Yadir Martinez Vergara
     * @return arreglo    Arreglo con la configuracion y valor de cada variables.
     */
     public function obtenerConfValoresVariablesGlobales($identidad, $arrCargos){
        $sql = "select cvg.*, nvg.idnivelconfiguracion 
					from mod_nomina.conf_variableglobalvalor cvg
					inner join mod_nomina.nom_variableglobal nvg on (nvg.idvariableglobal = cvg.idvariableglobal)
					where nvg.idnivelconfiguracion = 1 or cvg.identidad = ? or idcargo in (".implode(',',$arrCargos).")
					order by nvg.idnivelconfiguracion";

		$mg = Doctrine_Manager::getInstance();
		$conn = $mg->getCurrentConnection();
		return $conn->fetchAll($sql, array($identidad));
    }

    /**
     * Obtener la configuraci�n y valores de las variables globales para usar en la nomina
